/* chain.plsw -- Control Block Chain Demo
 * Allocates CVT/ASCB/ASXB/TCB from a bump arena,
 * wires pointer chain. Verify with --dump. */

%INCLUDE cvt;
DCL CVTPTR PTR;
%INCLUDE ascb;
DCL ASCBPTR PTR;
%INCLUDE asxb;
DCL ASXBPTR PTR;
%INCLUDE tcb;
DCL TCBPTR PTR;

/* --- Arena --- */
DCL ARENA(512) BYTE;
DCL ARENA_POS INT INIT(0);

