/* Storage classes */
DCL COUNTER INT STATIC;
DCL TEMP INT AUTOMATIC;     /* default for locals */
DCL SYM INT EXTERNAL;
```

### Procedures

```plsw
/* Simple procedure */
MAIN: PROC;
    CALL UART_PUTS(ADDR(MSG));
END;

/* With parameters and return type */
ADD: PROC(A INT, B INT) RETURNS(INT);
    RETURN(A + B);
END;

/* Call as expression (without CALL keyword) */
RESULT = ADD(3, 4);

/* No-argument function call -- parentheses required (PL/I rule) */
COUNT = GET_COUNT();      /* correct: function call */
COUNT = GET_COUNT;        /* WRONG: treated as variable reference */

/* Call as statement */
CALL UART_PUTS(ADDR(MSG));

/* Naked procedure (no prologue/epilogue) */
ISR: PROC OPTIONS(NAKED);
    ASM DO;
        'push    r0';
        'pop     r0';
        'jmp     (iv)';
    END;
END;
```

### Control Flow

```plsw
/* IF/THEN */
IF (COUNT > 0) THEN
    CALL PROCESS();

/* IF/THEN/ELSE with blocks */
IF (X = 0) THEN DO;
    X = 1;
END;
ELSE DO;
    X = 0;
END;

/* DO WHILE */
DO WHILE (COUNT > 0);
    COUNT = COUNT - 1;
END;

/* Counted DO */
DO I = 1 TO 10;
    CALL PRINT_INT(I);
END;
```

### Expressions

```plsw
/* Arithmetic: +, -, *, / */
X = A + B * C;
D = N / 10;

/* Comparison: =, <, >, <=, >=, != */
IF (X >= 10) THEN ...

/* Bitwise: &, |, ^, ~ */
FLAGS = FLAGS & MASK;

/* Pointer arithmetic */
NEXT = PTR + 3;

/* Address-of */
P = ADDR(VARIABLE);
P = ADDR(RECORD);

/* Size-of (compile-time record size) */
SZ = SIZEOF(CVT);
P = ALLOC(SIZEOF(ASCB));
```

### Record and Pointer Access

```plsw
/* Direct field access */
POINT.X = 100;
POINT.Y = 200;

/* Pointer dereference */
CVTPTR->CVTEYE = 'CVT ';    /* string literal to CHAR array field */
CVTPTR->CVTASCBH = ASCBPTR;  /* pointer field */

/* Array access */
