    EXPECTED = LEN + 6;

    _PLSW_BP = BLOCK;
    /* Double-free / invalid-pointer check */
    IF (_PLSW_BP->_PLSW_BLOCK_NEXT != _PLSW_ALLOC_MAGIC) THEN
        RETURN(1);
    /* Size mismatch */
    IF (_PLSW_BP->_PLSW_BLOCK_SIZE != EXPECTED) THEN
        RETURN(2);

    /* Sorted insert: find PREV, CURR with PREV < BLOCK <= CURR */
    PREV = 0;
    CURR = _PLSW_FREE_HEAD;
    DO WHILE (CURR != 0);
        IF (CURR >= BLOCK) THEN
            CURR = CURR;  /* found insertion point; loop exits below */
        ELSE DO;
            PREV = CURR;
            _PLSW_BP = CURR;
            CURR = _PLSW_BP->_PLSW_BLOCK_NEXT;
        END;
        IF (CURR >= BLOCK) THEN
            CURR_NEXT = 0;  /* dummy; see exit below */
    END;
